    if not w: continue
    r=len(set(w))/len(w)
    ratios.append((r, f.split('/')[-1][:60], len(w)))
ratios.sort()
print('lowest unique-word ratios:')
for r,n,w in ratios[:12]: print(f'  {r:.3f} {n} ({w}w)')
print('median:', f\"{ratios[len(ratios)//2][0]:.3f}\")
print('highest:'); 
for r,n,w in ratios[-3:]: print(f'  {r:.3f} {n} ({w}w)')
